[
  {
    "id": "take_cart_at_start",
    "text": "A shopper is obliged to acquire a cart near the beginning of the shopping trip.",
    "abstraction": {
      "state_properties": {
        "noCart": {
          "not": "hasCart"
        }
      },
      "events": {
        "acquireCart": {
          "pre": {
            "and": [
              "INTERACT",
              "noCart"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "acquireCart"
    },
    "justification": "The rule is defined by the cart-acquisition state transition rather than by the coordinates of a particular cart station."
  },
  {
    "id": "no_exit_without_cart",
    "text": "A shopper is forbidden to leave the store without still having a cart.",
    "abstraction": {
      "state_properties": {
        "noCart": {
          "not": "hasCart"
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "noCart"
        ]
      }
    },
    "justification": "The rule refers only to the universal exit action and cart possession, so it is independent of the exit cell's location."
  },
  {
    "id": "no_cart_in_single_file_aisle",
    "text": "A shopper must not have a cart while occupying a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    },
    "justification": "Single-file aisles are identified by local free-space geometry rather than by any store-specific aisle coordinates."
  },
  {
    "id": "no_cart_entry_into_single_file_aisle",
    "text": "A shopper is forbidden to move into a single-file aisle while pushing or holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    },
    "justification": "The prohibited transition is defined by entering locally narrow geometry with a cart, which is meaningful in any layout."
  },
  {
    "id": "do_not_park_cart_in_single_file_aisle",
    "text": "A shopper is forbidden to set down or park a cart inside a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "noCart": {
          "not": "hasCart"
        },
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": "noCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          "singleFileAisle"
        ]
      }
    },
    "justification": "The rule uses the act of relinquishing a cart and the local aisle width, not the identity of any particular parking cell."
  },
  {
    "id": "reclaim_cart_only_outside_single_file_aisle",
    "text": "A shopper is forbidden to pick up or reclaim a cart while standing in a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "noCart": {
          "not": "hasCart"
        },
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "acquireCart": {
          "pre": {
            "and": [
              "INTERACT",
              "noCart"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "acquireCart",
          "singleFileAisle"
        ]
      }
    },
    "justification": "Cart reclamation is constrained by local passage width rather than by a named location in either store."
  },
  {
    "id": "recover_cart_after_parking",
    "text": "After setting down a cart, a shopper is obliged to recover a cart before the trip ends.",
    "abstraction": {
      "state_properties": {
        "noCart": {
          "not": "hasCart"
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": "noCart"
        },
        "acquireCart": {
          "pre": {
            "and": [
              "INTERACT",
              "noCart"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "setDownCart",
      "discharge": "acquireCart"
    },
    "justification": "The norm is expressed over cart handoff events, so it applies no matter where a store permits cart parking."
  },
  {
    "id": "recover_cart_after_shopping_on_foot",
    "text": "After interacting with a shelf while not having a cart, a shopper is obliged to recover a cart before leaving.",
    "abstraction": {
      "state_properties": {
        "noCart": {
          "not": "hasCart"
        }
      },
      "events": {
        "footShelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "adjShelf",
              "noCart"
            ]
          },
          "post": null
        },
        "acquireCart": {
          "pre": {
            "and": [
              "INTERACT",
              "noCart"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "footShelfInteraction",
      "discharge": "acquireCart"
    },
    "justification": "The trigger uses shelf adjacency and cart absence rather than item-cell coordinates, so it generalizes across shelf layouts."
  }
]

